def fetch(entry):
    path=pathlib.Path(entry['path'])
    for attempt in range(3):
        try:
            req=urllib.request.Request(entry['url'],headers={'User-Agent':'MESORA-repository-import/1.0'})
            with urllib.request.urlopen(req,timeout=90) as response: raw=response.read()
            if hashlib.sha256(raw).hexdigest()!=entry['sha256']: raise ValueError('Release hash mismatch: '+str(path))
            path.parent.mkdir(parents=True,exist_ok=True);path.write_bytes(raw)
            return str(path)
        except Exception:
            if attempt==2: raise
            time.sleep(2)
if __name__=='__main__':
    for name,encoded in EMBEDDED.items():
        path=pathlib.Path(name);path.parent.mkdir(parents=True,exist_ok=True);path.write_bytes(base64.b64decode(encoded))
    with concurrent.futures.ThreadPoolExecutor(max_workers=4) as pool:
        for name in pool.map(fetch,REMOTE): print('Imported',name,flush=True)
    print('Imported',len(REMOTE)+len(EMBEDDED),'verified application files')
